import os
from web3 import Web3

_w3 = Web3(Web3.HTTPProvider(os.environ["ETH_RPC_URL"]))
_ABI = [
    {"constant": True, "inputs": [{"name": "o", "type": "address"}, {"name": "s", "type": "address"}], "name": "allowance", "outputs": [{"name": "", "type": "uint256"}], "type": "function"},
    {"constant": False, "inputs": [{"name": "s", "type": "address"}, {"name": "a", "type": "uint256"}], "name": "approve", "outputs": [{"name": "", "type": "bool"}], "type": "function"},
]


def list_and_revoke_token_approvals(owner_address: str, token_address: str, spender_address: str) -> dict:
    for value in (owner_address, token_address, spender_address):
        if not Web3.is_address(value):
            return {"ok": False, "error": f"invalid address: {value}"}
    owner = Web3.to_checksum_address(owner_address)
    if owner != Web3.to_checksum_address(os.environ.get("WALLET_ADDRESS", owner)):
        return {"ok": False, "error": "owner is not the managed wallet"}
    contract = _w3.eth.contract(address=Web3.to_checksum_address(token_address), abi=_ABI)
    spender = Web3.to_checksum_address(spender_address)
    current = contract.functions.allowance(owner, spender).call()
    if current == 0:
        return {"ok": True, "previous_allowance": 0, "revoked": False}
    tx = contract.functions.approve(spender, 0).build_transaction({
        "from": owner,
        "nonce": _w3.eth.get_transaction_count(owner),
    })
    signed = _w3.eth.account.sign_transaction(tx, os.environ["WALLET_PRIVATE_KEY"])
    tx_hash = _w3.eth.send_raw_transaction(signed.raw_transaction)
    return {"ok": True, "previous_allowance": current, "revoked": True, "tx_hash": tx_hash.hex()}
